export async function callTool(name, args) {
  if (name !== 'catalog_search') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Validate no extra keys
  const allowed = new Set(['query', 'offset', 'limit']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unexpected argument: ${key}`);
    }
  }

  // Validate query is a string
  if (typeof args.query !== 'string') {
    throw new Error('query must be a string');
  }

  // Parse offset
  let offset = 0;
  if ('offset' in args) {
    if (!Number.isInteger(args.offset) || args.offset < 0) {
      throw new Error('offset must be a non-negative integer');
    }
    offset = args.offset;
  }

  // Parse limit
  let limit = 2;
  if ('limit' in args) {
    if (!Number.isInteger(args.limit) || args.limit < 1 || args.limit > 5) {
      throw new Error('limit must be an integer between 1 and 5');
    }
    limit = args.limit;
  }

  // Search case-insensitively
  const query = args.query.toLowerCase();
  const matches = items.filter(item => item.name.toLowerCase().includes(query));

  // Paginate
  const page = matches.slice(offset, offset + limit);
  const nextOffset = offset + limit < matches.length ? offset + limit : null;

  let text;
  if (page.length === 0) {
    text = 'No items found.';
  } else {
    const lines = page.map(item => `${item.id}: ${item.name}`);
    if (nextOffset !== null) {
      lines.push(`next_offset: ${nextOffset}`);
    }
    text = lines.join('\n');
  }

  return { content: [{ type: 'text', text }] };
}
